add_filter( 'woocommerce_checkout_fields', 'perfectpixel_change_autofocus_field', 9999 );

function perfectpixel_change_autofocus_field( $fields ) {
	$target = '{{autofocus_field}}';
	foreach ( $fields as $group => $group_fields ) {
		foreach ( $group_fields as $key => $field ) {
			$fields[ $group ][ $key ]['autofocus'] = ( $key === $target );
		}
	}
	return $fields;
}
